{"content":"// Fused grouped experts kernel: direction (a), ONE Metal kernel, no sort/unsort.
//
// Threadgroup e (0..59) serves every (row, slot) pair routed to expert e, in
// chunks of 4 pairs. Gate/up/down products plus the silu-mul activation are
// fused; hidden pairs stay in threadgroup memory.
//
// Numerics replicate the reference bit-exactly (required: down outputs near
// cancellation amplify even 1-ULP hidden flips past the 2-ULP floor):
// - Each product replicates MLX affine_gather_qvm (mlx v0.32.4
//   backend/metal/kernels/quantized.h qvm_impl:1222-1330): lane l of a
//   simdgroup accumulates k = l, l+32, ... sequentially with qouter's exact
//   bits=4 forms (:503-509: s0*(low nibble)+bias, (s0/16)*(unshifted high
//   nibble)+bias), then a real simd_sum over the same lane mapping; lane 0
//   rounds to bfloat.
// - The activation replicates the compiled swiglu tape (compiled.cpp:206-208
//   rounds every op to its bf16 dtype): Sigmoid with T=bfloat per unary_ops.h
//   (:308-314, precise::exp rounded through bfloat per bf16_math.h), then two
//   bfloat multiplies.
// Weight reads are coalesced consecutive words along the out dim; x rows stay
// L1-resident. Valid for every row count 1..32 (grid rows-independent; rows
// from x_shape[0]; all indexing in bounds; validity-gated stores only).
using namespace metal;

threadgroup bfloat hbuf[4 * 384];
threadgroup ushort pcodes[128];
threadgroup uint npairs;

{
    uint tid = thread_position_in_threadgroup.x;
    uint lane = thread_index_in_simdgroup;
    uint sg = simdgroup_index_in_threadgroup;
    uint e = threadgroup_position_in_grid.x;
    int rows = x_shape[0];

    // Pair scan: one thread collects the (row, slot) codes routed to expert e.
    if (tid == 0) {
        uint n = 0;
        for (int r = 0; r < rows; ++r) {
            for (uint j = 0; j < 4; ++j) {
                if (inds[r * 4 + j] == e) {
                    pcodes[n++] = (ushort)(r * 4 + j);
                }
            }
        }
        npairs = n;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    uint n = npairs;

    uint gate_base = e * 768;
    uint down_base = e * 384;

    for (uint base = 0; base < n; base += 4) {
        uint nloc = min(n - base, 4u);

        // Gate/up/silu: 16 simdgroups x 96 iters = 4*384 (pair, output).
        for (uint it = 0; it < 96; ++it) {
            uint q = sg * 96 + it;
            uint p = q / 384;
            uint o = q % 384;
            uint code = (p < nloc) ? pcodes[base + p] : 0;
            uint r = code / 4;
            uint ow = o / 8;
            uint og = o / 32;
            uint bsh = 8 * ((o >> 1) & 3);
            bool odd = (o & 1);

            float gacc = 0.0f;
            if (!odd) {
                for (uint t = 0; t < 24; ++t) {
                    uint k = lane + t * 32;
                    float x = (float)x[r * 768 + k];
                    uint srow = (gate_base + k) * 12;
                    float s0 = (float)gate_scales[srow + og];
                    float bias = (float)gate_biases[srow + og];
                    uint word = gate_w[(gate_base + k) * 48 + ow];
                    uint byte = (word >> bsh) & 0xFFu;
                    gacc += x * (s0 * (byte & 0xFu) + bias);
                }
            } else {
                for (uint t = 0; t < 24; ++t) {
                    uint k = lane + t * 32;
                    float x = (float)x[r * 768 + k];
                    uint srow = (gate_base + k) * 12;
                    float s0 = (float)gate_scales[srow + og];
                    float s1 = s0 / 16.0f;
                    float bias = (float)gate_biases[srow + og];
                    uint word = gate_w[(gate_base + k) * 48 + ow];
                    uint byte = (word >> bsh) & 0xFFu;
                    gacc += x * (s1 * (byte & 0xF0u) + bias);
                }
            }
            float gsum = simd_sum(gacc);

            float uacc = 0.0f;
            if (!odd) {
                for (uint t = 0; t < 24; ++t) {
                    uint k = lane + t * 32;
                    float x = (float)x[r * 768 + k];
                    uint srow = (gate_base + k) * 12;
                    float s0 = (float)up_scales[srow + og];
                    float bias = (float)up_biases[srow + og];
                    uint word = up_w[(gate_base + k) * 48 + ow];
                    uint byte = (word >> bsh) & 0xFFu;
                    uacc += x * (s0 * (byte & 0xFu) + bias);
                }
            } else {
                for (uint t = 0; t < 24; ++t) {
                    uint k = lane + t * 32;
                    float x = (float)x[r * 768 + k];
                    uint srow = (gate_base + k) * 12;
                    float s0 = (float)up_scales[srow + og];
                    float s1 = s0 / 16.0f;
                    float bias = (float)up_biases[srow + og];
                    uint word = up_w[(gate_base + k) * 48 + ow];
                    uint byte = (word >> bsh) & 0xFFu;
                    uacc += x * (s1 * (byte & 0xF0u) + bias);
                }
            }
            float usum = simd_sum(uacc);

            // Exact compiled-swiglu tape in bfloat (see header comment).
            if (lane == 0 && p < nloc) {
                bfloat g16 = bfloat(gsum);
                bfloat u16 = bfloat(usum);
                bfloat a16 = bfloat(fabs((float)g16));
                bfloat e16 = bfloat(precise::exp((float)a16));
                bfloat d16 = bfloat(1.0f) + e16;
                bfloat y16 = bfloat(1.0f) / d16;
                bfloat sig =
                    (g16 < bfloat(0.0f)) ? y16 : (bfloat(1.0f) - y16);
                bfloat silu = g16 * sig;
                hbuf[p * 384 + o] = silu * u16;
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);

        // Down: 16 simdgroups x 192 iters = 4*768 (pair, output).
        for (uint it = 0; it < 192; ++it) {
            uint q = sg * 192 + it;
            uint p = q / 768;
            uint d = q % 768;
            uint code = (p < nloc) ? pcodes[base + p] : 0;
            uint r = code / 4;
            uint j = code % 4;
