                    float gbias = (float)gate_biases[gsrow + og];
                    uint uword = up_w[gwrow + ow];
                    uint ubyte = (uword >> bsh) & 0xFFu;
                    float us0 = (float)up_scales[gsrow + og];
                    float ubias = (float)up_biases[gsrow + og];
