            uint code1 = 0;
            if (v1) {
                code1 = pcodes[base + p0 + 1];
            }
            uint r0 = code0 / 4;
            uint j0 = code0 % 4;
            uint r1 = code1 / 4;
            uint j1 = code1 % 4;

            float yacc[16] = {0.0f};
            for (uint t = 0; t < 12; ++t) {
                uint h = lane + t * 32;
                uint dwrow = (down_base + h) * 96;
                uint dsrow = (down_base + h) * 24;
                for (uint m = 0; m < 16; ++m) {
                    bool lo = m < msplit;
                    uint q = q0 + m;
                    uint p = lo ? p0 : p0 + 1;
                    uint d = q - p * 768;
                    uint dw = d / 8;
                    uint dg = d / 32;
                    uint bsh = 8 * ((d >> 1) & 3);
                    float xv = (float)hbuf[p * 384 + h];
                    uint word = down_w[dwrow + dw];
                    uint byte = (word >> bsh) & 0xFFu;
                    float s0 = (float)down_scales[dsrow + dg];
                    float bias = (float)down_biases[dsrow + dg];
                    if (d & 1) {
                        float s1 = s0 / 16.0f;
                        yacc[m] += xv * (s1 * (byte & 0xF0u) + bias);
                    } else {
                        yacc[m] += xv * (s0 * (byte & 0xFu) + bias);
                    }
                }
            }
            if (lane == 0) {
                for (uint m = 0; m < 16; ++m) {
                    bool lo = m < msplit;
                    uint p = lo ? p0 : p0 + 1;
                    if ((lo ? v0 : v1)) {
                        uint q = q0 + m;
                        uint d = q - p * 768;
                        uint r = lo ? r0 : r1;
                        uint j = lo ? j0 : j1;
                        y[(r * 4 + j) * 768 + d] = bfloat(yacc[m]);
                    }
                }
            }
        }
        // Next chunk overwrites hbuf; all down reads above must be done.
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
