{"content":"// Fused grouped experts kernel: direction (a), ONE Metal kernel, no sort/unsort.
//
// Threadgroup e (0..59) serves every (row, slot) pair routed to expert e, in
// chunks of 4 pairs. Gate/up/down products plus the silu-mul activation are
// fused; gate/up/hidden pairs stay in threadgroup memory.
//
// Numerics replicate the reference bit-exactly (required: down outputs near
// cancellation amplify even 1-ULP hidden flips past the 2-ULP floor):
// - Each product replicates MLX affine_gather_qvm (mlx v0.32.4
//   backend/metal/kernels/quantized.h qvm_impl:1222-1330): lane l of a
//   simdgroup accumulates k = l, l+32, ... sequentially with qouter's exact
//   bits=4 forms (:503-509: s0*(low nibble)+bias, (s0/16)*(unshifted high
//   nibble)+bias), then a real simd_sum over the same lane mapping; lane 0
//   rounds to bfloat.
// - The activation replicates the compiled swiglu tape (compiled.cpp:206-208
//   rounds every op to its bf16 dtype): Sigmoid with T=bfloat per unary_ops.h
//   (:308-314, precise::exp rounded through bfloat per bf16_math.h), then two
//   bfloat multiplies.
// Inner loops are fully static: each 16-output block starts at a 16-multiple
// o0 (q0 and p*384 are both 16-multiples), so o0%8==0 (two fixed word runs),
// o0%32 is 0 or 16 (one scale group, no clamps), o0 is even (8 direct
// even/odd pairs sharing one byte each, bsh = 8*(j&3) constant). No selects,
// branches, or clamps in the inner loop: ~5.5 ops/MAC. Each 128-q block holds
// one pair, so blocks past nloc are skipped exactly (no dummy work).
// Valid for every row count 1..32 (grid rows-independent; rows from
// x_shape[0]; all indexing in bounds; validity-gated stores only).
using namespace metal;

threadgroup bfloat gbuf[4 * 384];
threadgroup bfloat ubuf[4 * 384];
threadgroup bfloat hbuf[4 * 384];
threadgroup ushort pcodes[128];
threadgroup uint npairs;

{
    uint tid = thread_position_in_threadgroup.x;
    uint lane = thread_index_in_simdgroup;
    uint sg = simdgroup_index_in_threadgroup;
    uint e = threadgroup_position_in_grid.x;
    int rows = x_shape[0];

    // Pair scan: one thread collects the (row, slot) codes routed to expert e.
    if (tid == 0) {
        uint n = 0;
        for (int r = 0; r < rows; ++r) {
            for (uint j = 0; j < 4; ++j) {
                if (inds[r * 4 + j] == e) {
                    pcodes[n++] = (ushort)(r * 4 + j);
                }
            }
        }
        npairs = n;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    uint n = npairs;

    uint gate_base = e * 768;
    uint down_base = e * 384;

    for (uint base = 0; base < n; base += 4) {
        uint nloc = min(n - base, 4u);

        // Gate: 12 blocks x 128 = 4*384 (pair, output), 16 per simdgroup.
        for (uint itb = 0; itb < 12; ++itb) {
            uint p = (itb * 128) / 384;
            if (p >= nloc) {
                continue;
            }
            uint q0 = itb * 128 + sg * 16;
            uint code = pcodes[base + p];
            uint r = code / 4;
            uint o0 = q0 - p * 384;
            uint ow0 = o0 / 8;
            uint og0 = o0 / 32;

            float acc[16] = {0.0f};
            for (uint t = 0; t < 24; ++t) {
                uint k = lane + t * 32;
                float xv = (float)x[r * 768 + k];
                uint gwrow = (gate_base + k) * 48;
                uint gsrow = (gate_base + k) * 12;
                uint w0 = gate_w[gwrow + ow0];
                uint w1 = gate_w[gwrow + ow0 + 1];
                float s0 = (float)gate_scales[gsrow + og0];
                float b0 = (float)gate_biases[gsrow + og0];
                float s0d = s0 / 16.0f;
#pragma clang loop unroll(full)
                for (uint j = 0; j < 4; ++j) {
                    uint byte = (w0 >> (8 * j)) & 0xFFu;
                    acc[2 * j] += xv * (s0 * (byte & 0xFu) + b0);
                    acc[2 * j + 1] += xv * (s0d * (byte & 0xF0u) + b0);
                }
#pragma clang loop unroll(full)
                for (uint j = 4; j < 8; ++j) {
                    uint byte = (w1 >> (8 * (j - 4))) & 0xFFu;
                    acc[2 * j] += xv * (s0 * (byte & 0xFu) + b0);
                    acc[2 * j + 1] += xv * (s0d * (byte & 0xF0u) + b0);
                }
            }
#pragma clang loop unroll(full)
            for (uint m = 0; m < 16; ++m) {
                acc[m] = simd_sum(acc[m]);
            }
            if (lane == 0) {
#pragma clang loop unroll(full)
                for (uint m = 0; m < 16; ++m) {
                    gbuf[p * 384 + o0 + m] = bfloat(acc[m]);
                }
            }
        }

        // Up: same structure, up weights.
        for (uint itb = 0; itb < 12; ++itb) {
            uint p = (itb * 128) / 384;
            if (p >= nloc) {
                continue;
            }
            uint q0 = itb * 128 + sg * 16;
            uint code = pcodes[base + p];
            uint r = code / 4;
            uint o0 = q0 - p * 384;
            uint ow0 = o0 / 8;
            uint og0 = o0 / 32;

            float acc[16] = {0.0f};
            for (uint t = 0; t < 24; ++t) {
                uint k = lane + t * 32;
                float xv = (float)x[r * 768 + k];
                uint gwrow = (gate_base + k) * 48;
                uint gsrow = (gate_base + k) * 12;
                uint w0 = up_w[gwrow + ow0];
                uint w1 = up_w[gwrow + ow0 + 1];
                float s0 = (float)up_scales[gsrow + og0];
                float b0 = (float)up_biases[gsrow + og0];
                float s0d = s0 / 16.0f;
#pragma clang loop unroll(full)
                for (uint j = 0; j < 4; ++j) {
                    uint byte = (w0 >> (8 * j)) & 0xFFu;
                    acc[2 * j] += xv * (s0 * (byte & 0xFu) + b0);
                    acc[2 * j + 1] += xv * (s0d * (byte & 0xF0u) + b0);
                }
#pragma clang loop unroll(full)
                for (uint j = 4; j < 8; ++j) {
                    uint byte = (w1 >> (8 * (j - 4))) & 0xFFu;
                    acc[2 * j] += xv * (s0 * (byte & 0xFu) + b0);
                    acc[2 * j + 1] += xv * (s0d * (byte & 0xF0u) + b0);
                }
            }
#pragma clang loop unroll(full)
            for (uint m = 0; m < 16; ++m) {
                acc[m] = simd_sum(acc[m]);
            }
            if (lane == 0) {
#pragma clang loop unroll(full)
                for (uint m = 0; m < 16; ++m) {
                    ubuf[p * 384 + o0 + m] = bfloat(acc[m]);
                }
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);

        // silu-mul: exact compiled-swiglu tape in bfloat (see header comment).
        for (uint l = tid * 6; l < tid * 6 + 6; ++l) {
            uint p = l / 384;
            uint o = l % 384;
            if (p < nloc) {
                bfloat g16 = gbuf[p * 384 + o];
                bfloat u16 = ubuf[p * 384 + o];
                bfloat a16 = bfloat(fabs((float)g16));
                bfloat e16 = bfloat(precise::exp((float)a16));
                bfloat d16 = bfloat(1.0f) + e16;
                bfloat y16 = bfloat(1.0f) / d16;
                bfloat sig =
                    (g16 < bfloat(0.0f)) ? y16 : (bfloat(1.0f) - y16);
                bfloat silu = g16 * sig;
                hbuf[p * 384 + o] = silu * u16;
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);

        // Down: 24 blocks x 128 = 4*768 (pair, output), 16 per simdgroup.
        for (uint itb = 0; itb < 24; ++itb) {
            uint p = (itb * 128) / 768;
            if (p >= nloc) {
                continue;
            }
            uint q0 = itb * 128 + sg * 16;
            uint code = pcodes[base + p];
            uint r = code / 4;
            uint j = code % 4;
            uint d0 = q0 - p * 768;
            uint dw0 = d0 / 8;
            uint dg0 = d0 / 32;

            float acc[16] = {0.0f};
            for (uint t = 0; t < 12; ++t) {
                uint h = lane + t * 32;
                float xv = (float)hbuf[p * 384 + h];
                uint dwrow = (down_base + h) * 96;
                uint dsrow = (down_base + h) * 24;
                uint w0 = down_w[dwrow + dw0];
                uint w1 = down_w[dwrow + dw0 + 1];
                float s0 = (float)down_scales[dsrow + dg0];
                float b0 = (float)down_biases[dsrow + dg0];
                float s0d = s0 / 16.0f;
#pragma clang loop unroll(full)
                for (uint jj = 0; jj < 4; ++jj) {
                    uint byte = (w0 >> (8 * jj)) & 0xFFu;
                    acc[2 * jj] += xv * (s0 * (byte & 0xFu) + b0);
                    acc[2 * jj + 1] += xv * (s0d * (byte & 0xF0u) + b0);
                }
#pragma clang loop unroll(full)
                for (uint jj = 4; jj < 8; ++jj) {
                    uint byte = (w1 >> (8 * (jj - 4))) & 0xFFu;
                    acc[2 * jj] += xv * (s0 * (byte & 0xFu) + b0);
                    acc[2 * jj + 1] += xv * (s0d * (byte & 0xF0u) + b0);
                }
            }
#pragma clang loop unroll(full)
            for (uint m = 0; m < 16; ++m) {
                acc[m] = simd_sum(acc[m]);
            }
            if (lane == 0) {
#pragma clang loop unroll(full)
