{"content":"// hyp-1 direction (b): one threadgroup per (row, expert-slot) pair.
// Fuses gate/up/down products + silu-mul with intermediates in threadgroup
// memory. Each expert's weights are still read once per pair: no cross-pair
// batching, no sort. Grid: rows*4 pairs x 128 threads.
uint pair = threadgroup_position_in_grid.x;
uint tid = thread_position_in_threadgroup.x;
uint r = pair >> 2;
uint e = inds[pair];

threadgroup bfloat tg_x[768];
threadgroup bfloat tg_gate[384];
threadgroup bfloat tg_up[384];
threadgroup bfloat tg_h[384];

// Cooperative load of the input row; gate/up/down all reuse it on-chip.
for (uint i = tid; i < 768u; i += 128u) {
    tg_x[i] = x[r * 768u + i];
}
threadgroup_barrier(metal::mem_flags::mem_threadgroup);

// gate/up: 3 outputs per thread, one shared i-loop (x[i] read once).
uint o0 = tid * 3u;
ulong gw_e = (ulong)e * 36864ul; // [60,768,48] expert stride, words
ulong gs_e = (ulong)e * 9216ul;  // [60,768,12] expert stride
