  uint b = v * 4u + simd;
  qvm_block(up_w + eW, up_scales + eS, up_biases + eS, tg_x, 768u, 12u, 48u, b, b * 4u, lane, p);
  if (lane == 0) {
    for (uint j = 0; j < 32u; ++j) {
